package gui;
import java.awt.*;import java.awt.event.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import datos.DatosSistema;import entidad.*;
public class FormReceta extends JInternalFrame{
 private JComboBox<Paciente> cboPaciente;private JTextField txtMedicamento,txtIndicaciones,txtBuscar;private DefaultTableModel model;
 public FormReceta(){setTitle("Proceso: Emitir Receta Médica");setClosable(true);setMaximizable(true);setIconifiable(true);setBounds(90,60,600,420);getContentPane().setLayout(new BorderLayout(5,5));JPanel f=new JPanel(new GridLayout(4,2,5,5));f.setBorder(BorderFactory.createTitledBorder("Emitir Nueva Receta"));f.add(new JLabel(" Paciente:"));cboPaciente=new JComboBox<>();f.add(cboPaciente);f.add(new JLabel(" Medicamento:"));txtMedicamento=new JTextField();f.add(txtMedicamento);f.add(new JLabel(" Indicaciones:"));txtIndicaciones=new JTextField();f.add(txtIndicaciones);JButton b=new JButton("Guardar Receta");b.addActionListener(e->emitir());f.add(b);JPanel s=new JPanel(new BorderLayout());s.setBorder(BorderFactory.createTitledBorder("Buscar Receta por Paciente o Medicamento"));txtBuscar=new JTextField();txtBuscar.addKeyListener(new KeyAdapter(){public void keyReleased(KeyEvent e){actualizarRecetas(txtBuscar.getText().trim());}});s.add(txtBuscar);JPanel n=new JPanel(new BorderLayout());n.add(f,BorderLayout.CENTER);n.add(s,BorderLayout.SOUTH);getContentPane().add(n,BorderLayout.NORTH);model=new DefaultTableModel(new Object[]{"ID","Paciente","Medicamento","Indicaciones"},0);getContentPane().add(new JScrollPane(new JTable(model)),BorderLayout.CENTER);}
 public void actualizarRecetas(String filtro){cboPaciente.removeAllItems();for(Paciente p:DatosSistema.pacientes)cboPaciente.addItem(p);model.setRowCount(0);for(Receta r:DatosSistema.recetas)if(r.getPaciente().getNombre().toLowerCase().contains(filtro.toLowerCase())||r.getMedicamento().toLowerCase().contains(filtro.toLowerCase()))model.addRow(new Object[]{r.getId(),r.getPaciente().getNombre(),r.getMedicamento(),r.getIndicaciones()});}
 private void emitir(){if(cboPaciente.getSelectedItem()!=null&&!txtMedicamento.getText().trim().isEmpty()){String id="R"+String.format("%03d",DatosSistema.recetas.size()+1);DatosSistema.recetas.add(new Receta(id,(Paciente)cboPaciente.getSelectedItem(),txtMedicamento.getText().trim(),txtIndicaciones.getText().trim()));actualizarRecetas("");FrmPrincipal.actualizarContadores();txtMedicamento.setText("");txtIndicaciones.setText("");JOptionPane.showMessageDialog(this,"Receta emitida con éxito.");}else JOptionPane.showMessageDialog(this,"Seleccione paciente e ingrese medicamento.");}
}
